import sqlite3

conn = sqlite3.connect('/data/maps/e2e_test_case_0.Civ6Map')
cursor = conn.cursor()

width = 44
height = 26

# Get all plot data
cursor.execute('SELECT ID, TerrainType, IsImpassable FROM Plots ORDER BY ID')
plots = {}
for row in cursor.fetchall():
    pid, terrain, impassable = row
    x = pid % width
    y = pid // width
    plots[pid] = {
        'id': pid, 'x': x, 'y': y,
        'terrain': terrain, 'impassable': impassable
    }

# Let's look at the land area around the main island (around x=20-27, y=10-18)
# and verify adjacency by looking at terrain patterns

# Print a visual map of the island area
