print("    ", end="")
for x in range(18, 31):
    print(f"{x:3d}", end="")
print()

for y in range(10, 19):
    print(f"y={y:2d} ", end="")
    for x in range(18, 31):
        pid = y * width + x
        p = plots.get(pid)
        if p:
            t = p['terrain']
            if 'MOUNTAIN' in t:
                ch = ' M '
            elif 'OCEAN' in t:
                ch = ' ~ '
            elif 'COAST' in t:
                if p['impassable']:
                    ch = ' . '
                else:
                    ch = ' c '
            elif 'GRASS' in t:
                ch = ' G '
            elif 'PLAINS' in t:
                ch = ' P '
            else:
                ch = ' ? '
        else:
            ch = '   '
        print(ch, end="")
    print()

# Now let's check the features on the island
cursor.execute('SELECT ID, FeatureType FROM PlotFeatures')
features = {}
for row in cursor.fetchall():
    features[row[0]] = row[1]

# Rivers
cursor.execute('SELECT * FROM PlotRivers')
rivers = {}
for row in cursor.fetchall():
    rivers[row[0]] = {
        'IsNEOfRiver': row[1], 'IsWOfRiver': row[2], 'IsNWOfRiver': row[3],
        'EFlowDirection': row[4], 'SEFlowDirection': row[5], 'SWFlowDirection': row[6]
    }

print("\nFeatures on island:")
for pid in sorted(features.keys()):
    if 18 <= (pid % width) <= 30 and 10 <= (pid // width) <= 18:
        x, y = pid % width, pid // width
        print(f"  ({x},{y}): {features[pid]}")

print("\nRivers on island:")
for pid in sorted(rivers.keys()):
    if 18 <= (pid % width) <= 30 and 10 <= (pid // width) <= 18:
        x, y = pid % width, pid // width
        r = rivers[pid]
        flags = []
        if r['IsNEOfRiver']: flags.append('NE')
        if r['IsWOfRiver']: flags.append('W')
        if r['IsNWOfRiver']: flags.append('NW')
        if r['EFlowDirection'] >= 0: flags.append(f'E_flow={r["EFlowDirection"]}')
        if r['SEFlowDirection'] >= 0: flags.append(f'SE_flow={r["SEFlowDirection"]}')
        if r['SWFlowDirection'] >= 0: flags.append(f'SW_flow={r["SWFlowDirection"]}')
        print(f"  ({x},{y}): {', '.join(flags)}")

